   "E claro que não podia faltar os lindos <a href=\"https://www.instagram.com/karinaprof2008/\" target=\"_blank\" rel=\"noopener\">@karinaprof2008</a> e <a href=\"https://www.instagram.com/prof_motta/\" target=\"_blank\" rel=\"noopener\">@prof_motta</a> que guiaram todo esse potencial ao longo dos anos. 🏆",
