  "title": "30.Mai | Festa da Família 2025 🌟",
  "cats": [
   "Novidades"
  ],
  "body": [
   "Uma noite pra lá de especial em? ✨",
   "O semestre está voando, o frio está aumentando, mas o calorzinho da ✨Festa da Família 2025✨ ainda aquece o coração! 💙🧡",
   "Confira com a gente essa celebração que teve:",
   "🎶 Música",
   "⚽ Esportes",
   "💞 E muita conexão",
   "Uma data que todo ano fortalece os laços entre pais, filhos e escola – porque família, diversão e aprendizado são memórias que a gente carrega pra sempre. 💖"
  ],
