   "Apresentamos a estrutura externa do nosso colégio. 👀",
   "Um ambiente que inspira aprendizado, criatividade e crescimento. ✨📓",
   "Um espaço amplo, que conta com: campo de futebol, quadra de beach tênis, quadra de futsal, parque de areia, jardins e áreas de convivência ao ar livre. ✨🎓🏫",
