 {
  "id": 3703,
  "date": "2019-06-03",
  "title": "Dicas e Calendário ENEM 2019",
  "cats": [
   "Assuntos Gerais"
  ],
  "body": [
   "Há praticamente cinco meses da prova do <a href=\"http://enem%20registra%20mais%20de%206%2C3%20milh%C3%B5es%20de%20inscritos/\" target=\"_blank\" rel=\"noopener\">Enem (Exame Nacional do Ensino Médio)</a>, estudantes devem focar seus esforços na redação e em revisar o conteúdo está é a principal orientação de especialistas ouvidos pelo R7. Confira algumas dicas para ajudar a estudar de forma efetiva para as provas que serão aplicadas em novembro.",
   "Redação",
   "Este é o ponto fundamental para ter sucesso no Enem. “A redação é muito valorizada na composição da nota”, diz professora língua portuguesa e produção textual do colégio Mopi Tatiana Nunes. Uma nota baixa na redação derruba todas as notas. “O peso do texto é grande no exame e os alunos devem estar atentos nisso”.",
   "O primeiro passo para conseguir redigir uma boa redação é, segundo Tatiana, ler. “É fundamental que o estudante leia para ter um bom repertório cultural”.",
   "“A redação é um divisor de águas, independente da área escolhida, exatas, humanas ou biológicas”, avalia Paulo Henrique Menezes, o idealizador da Escola de Apoio Meu Dever de Casa.  “O hábito da leitura é fundamental, oriento que o estudante leia as principais notícias do dia, escreva um pequeno resumo e no sábado produza uma redação sobre um desses temas, uma forma de ler, se manter bem informado e treinar o texto”.",
   "Assuntos da atualidade são apostas de temas para a redação. “Claro, estamos em um ano marcado por muitas mudanças, mas assuntos que estão em destaque merecem atenção”, observa Tatiana. Para a professora, questões como depressão, suicídio, bullying e meio ambiente são possíveis apostas de temas.",
   "Entender o enunciado e saber o que o exame pede é o ponto de partida para escrever um bom texto. “Organizar bem as ideias na redação, saber conectar as informações e os parágrafos são fundamentais para um texto coeso e coerente”.",
   "Revisão &amp; Dicas",
   "Não adianta querer aprender o conteúdo do ensino médio em apenas cinco meses. “Agora é hora de revisar o conteúdo, refazer as provas de anos anteriores”, observa Menezes. “Quem é de exatas, vale fazer exercícios e de humanos o foco é na leitura e interpretação de texto”.",
   "Para os professores, os estudantes devem dedicar ao menos 4 horas por dia para a revisão de matérias. Deixe o celular de lado e atenção total ao conteúdo. “É importante fazer um intervalo para descansar um pouco, isso ajuda a gravar melhor o conteúdo”, orienta Menezes.",
   "Caminhada e atividades físicas são fundamentais para liberar endorfina. Um estudante mais relaxado se concentra melhor e rende mais.",
   "Fonte e matéria original R7"
  ],
  "images": [
   {
    "t": "https://colegioholus.com.br/site/wp-content/uploads/2019/06/enem-enem-2019-17052019094252539.jpeg",
    "f": "https://colegioholus.com.br/site/wp-content/uploads/2019/06/enem-enem-2019-17052019094252539.jpeg"
   },
   {
    "t": "https://colegioholus.com.br/site/wp-content/uploads/2019/06/calendario-enem-2019-25042019114006616.jpeg",
    "f": "https://colegioholus.com.br/site/wp-content/uploads/2019/06/calendario-enem-2019-25042019114006616.jpeg"
   }
  ],
  "videos": [],
  "link": "https://colegioholus.com.br/site/2019/06/03/dicas-e-calendario-enem-2019/"
 }
